text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "比较一组和二组的平均响应分钟",
      "business_question": "在只看一组和二组的前提下，计算并比较这两个团队的平均响应分钟。",
      "priority": "P0",
      "priority_reason": "核心需求C01/C02/C03要求明确比较指定团队（一组、二组）的平均响应分钟。若删除此任务，无法回答用户关于团队效率对比的核心问题。虽然“平均”口径在uncertainties中未完全确认（可能需确认均值/中位数），但根据metric_requirements明确指向“平均”，且数据字段field_0005为整数类型支持avg运算，故规划为标准平均值计算。若执行时发现口径争议，将标记为待确认，但作为核心分析目标必须保留。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "一组",
                  "二组"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0005",
                "alias": "avg_response_minutes"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
